// #05b294 / #0fc9cd — экран /admin («ניהול חברות ומשתמשים»), роль platform admin. ТОЛЬКО ЧТЕНИЕ: ничего не блокируем,
// не создаём и не сохраняем; диалоги «חסימה» / «יצירת חברה חדשה» / «עריכה» открываем и закрываем «ביטול».
// Кейсы: .qa/tests/admin-companies-users/ACU-01..ACU-08. План: .qa/e2e/specs/admin-companies-users.md.
// ВНИМАНИЕ: вход platform один (Supabase, ротация токена) — файл идёт строго по порядку (serial) в ОДНОМ окне на весь файл;
// запускать с --workers=1 и не параллелить с другими тестами роли platform (admin-block-flow.spec.ts, mobile-tables/admin-mobile.spec.ts).
// «Нет компаний вообще», «загрузка» и «ошибка» воспроизводятся только через route-мок (живые данные есть) — отмечено в названиях.
import { test, expect, Page, BrowserContext } from '@playwright/test';
import {
  openRoleContext, openAdmin, trackMutations, companiesTable, usersTable, rowsOf, companiesHeading, usersHeading,
  searchBox, countIn, dialogOf, platformSession, sbRpc,
} from './helpers';

test.describe.configure({ mode: 'serial' });

let ctx: BrowserContext;
let page: Page;
let mutations: string[];

test.beforeAll(async ({ browser }, testInfo) => {
  ctx = await openRoleContext(browser, testInfo, 'platform');
  page = await ctx.newPage();
  mutations = trackMutations(page);
});
test.afterEach(async () => {
  await page.unrouteAll({ behavior: 'ignoreErrors' });
});
test.afterAll(async () => {
  await ctx?.close();
});

test.describe('ניהול חברות ומשתמשים — צפייה (platform)', () => {
  test('רשימת חברות ורשימת משתמשים עם עמודות, סטטוס וכפתור חסימה בכל שורה #05b294 @desktop @prod-safe', async () => {
    // ACU-01
    await openAdmin(page);
    await expect(page.getByText('מסך תפעולי לצוות המערכת.', { exact: true })).toBeVisible();
    await expect(searchBox(page)).toBeVisible();
    await expect(page.getByRole('button', { name: 'יצירת חברה חדשה' })).toBeVisible();

    const nCompanies = await countIn(companiesHeading(page));
    const nUsers = await countIn(usersHeading(page));
    expect(nCompanies).toBeGreaterThan(0);
    expect(nUsers).toBeGreaterThan(0);

    const ch = companiesTable(page).getByRole('columnheader');
    await expect(ch.filter({ hasText: 'שם החברה' })).toHaveCount(1);
    await expect(ch.filter({ hasText: 'משתמשים' })).toHaveCount(1);
    await expect(ch.filter({ hasText: 'סטטוס' })).toHaveCount(1);
    const uh = usersTable(page).getByRole('columnheader');
    for (const h of ['שם', 'אימייל', 'חברה', 'הרשאה', 'סטטוס']) await expect(uh.filter({ hasText: new RegExp(`^${h}$`) })).toHaveCount(1);

    // דרישה 1/2: מספר שורות = מספר בכותרת; דרישה 6/7: בכל שורה כפתור «חסימה» (או «ביטול חסימה» אם כבר חסום).
    const cRows = rowsOf(companiesTable(page));
    const uRows = rowsOf(usersTable(page));
    await expect(cRows).toHaveCount(nCompanies);
    await expect(uRows).toHaveCount(nUsers);
    const blockBtn = (r: ReturnType<Page['locator']>) => r.getByRole('button', { name: /^(ביטול )?חסימה$/ });
    await expect(cRows.filter({ has: blockBtn(page) })).toHaveCount(nCompanies);
    await expect(uRows.filter({ has: blockBtn(page) })).toHaveCount(nUsers);
    // כל שורה מסומנת באינדיקציה של סטטוס (דרישה 9).
    await expect(cRows.filter({ hasText: /פעילה|חסומה/ })).toHaveCount(nCompanies);
    await expect(uRows.filter({ hasText: /פעיל|חסום/ })).toHaveCount(nUsers);
  });

  test('הרשימות במסך תואמות לרשימות מהשרת (RPC platform_list_*) #0fc9cd @desktop @prod-safe', async () => {
    // ACU-02
    await openAdmin(page);
    const nCompanies = await countIn(companiesHeading(page));
    const nUsers = await countIn(usersHeading(page));
    const s = await platformSession(page);
    const companies = await sbRpc(s, 'platform_list_companies');
    const users = await sbRpc(s, 'platform_list_users');
    expect(companies.status, companies.text).toBe(200);
    expect(users.status, users.text).toBe(200);
    expect(Array.isArray(companies.json)).toBe(true);
    expect(Array.isArray(users.json)).toBe(true);
    expect(companies.json).toHaveLength(nCompanies);
    expect(users.json).toHaveLength(nUsers);
  });

  test('מצב טעינה: "טוען חברות ומשתמשים" עד שהרשימות חוזרות (השהיה בדמה) #05b294 @desktop @prod-safe', async () => {
    // ACU-03 — דרישה 3; השהיית הרשימות בדמה של הרשת (route), בלי השהיות קבועות
    let release!: () => void;
    const gate = new Promise<void>((r) => (release = r));
    await page.route(/rpc\/platform_list_(companies|users)/, async (route) => {
      await gate;
      await route.continue();
    });
    await page.goto('/admin');
    await expect(page.getByRole('heading', { name: 'ניהול חברות ומשתמשים', level: 1 })).toBeVisible();
    await expect(page.getByText(/^טוען חברות ומשתמשים/)).toBeVisible();
    await expect(companiesHeading(page)).toHaveCount(0);
    release();
    await expect(companiesHeading(page)).toBeVisible();
    await expect(page.getByText(/^טוען חברות ומשתמשים/)).toHaveCount(0);
  });

  test('מצב ריק כשאין חברות ומשתמשים בכלל (דמה: רשימות ריקות) #05b294 @desktop @prod-safe', async () => {
    // ACU-04 — דרישה 4; על נתונים חיים אי אפשר, בדיקה רק מול route-דמה
    await page.route(/rpc\/platform_list_(companies|users)/, (route) =>
      route.fulfill({ status: 200, contentType: 'application/json', body: '[]' }),
    );
    await page.goto('/admin');
    await expect(page.getByRole('heading', { name: 'חברות (0)' })).toBeVisible();
    await expect(page.getByRole('heading', { name: 'משתמשים (0)' })).toBeVisible();
    await expect(page.getByText('אין עדיין חברות במערכת', { exact: true })).toBeVisible();
    await expect(page.getByText('צרו חברה חדשה והזמינו את מנהל החשבון שלה.', { exact: true })).toBeVisible();
    await expect(page.getByText('אין עדיין משתמשים במערכת', { exact: true })).toBeVisible();
    await expect(page.locator('table')).toHaveCount(0);
  });

  test('שגיאת טעינה: הודעה "אירעה שגיאה. נסו שוב." וכפתור "נסו שוב" שמטעין מחדש (דמה: 500) #05b294 @desktop @prod-safe', async () => {
    // ACU-04 — ב-S-25 מצב שגיאה לא מוגדר (ממצא); התנהגות בפועל 17.11
    await page.route(/rpc\/platform_list_companies/, (route) =>
      route.fulfill({ status: 500, contentType: 'application/json', body: '{"message":"boom"}' }),
    );
    await page.goto('/admin');
    await expect(page.getByText('אירעה שגיאה. נסו שוב.', { exact: true })).toBeVisible();
    await expect(companiesHeading(page)).toHaveCount(0);
    await page.unrouteAll({ behavior: 'ignoreErrors' });
    await page.getByRole('button', { name: 'נסו שוב', exact: true }).click();
    await expect(companiesHeading(page)).toBeVisible();
    await expect(page.getByText('אירעה שגיאה. נסו שוב.', { exact: true })).toHaveCount(0);
  });

  test('חיפוש לפי שם חברה, אימייל ושם משתמש — ללא רגישות לרישיות; ריק מחזיר הכול #05b294 @desktop @prod-safe', async () => {
    // ACU-05 — דרישה 5
    await openAdmin(page);
    const total = { c: await countIn(companiesHeading(page)), u: await countIn(usersHeading(page)) };

    // שם חברה (אותיות קטנות)
    await searchBox(page).fill('qa company b');
    const cRows = rowsOf(companiesTable(page));
    await expect(cRows.first()).toBeVisible();
    const nFiltered = await cRows.count();
    expect(nFiltered).toBeGreaterThanOrEqual(1);
    expect(nFiltered).toBeLessThan(total.c);
    await expect(cRows.filter({ hasText: /QA Company B/i })).toHaveCount(nFiltered);
    await expect(companiesHeading(page)).toHaveText(`חברות (${nFiltered})`);

    // אימייל
    await searchBox(page).fill('QA-INV14');
    await expect(rowsOf(usersTable(page)).filter({ hasText: /qa-inv14/i }).first()).toBeVisible();
    expect(await countIn(usersHeading(page))).toBeLessThan(total.u);

    // שם משתמש
    await searchBox(page).fill('QA Member');
    await expect(rowsOf(usersTable(page)).filter({ hasText: /QA Member/i }).first()).toBeVisible();

    // ריק — הכול חוזר
    await searchBox(page).fill('');
    await expect(companiesHeading(page)).toHaveText(`חברות (${total.c})`);
    await expect(usersHeading(page)).toHaveText(`משתמשים (${total.u})`);
  });

  test('חיפוש בלי תוצאות: מצב ריק בשתי הרשימות, איפוס מחזיר את הרשימות #05b294 @desktop @prod-safe', async () => {
    // ACU-06 — דרישה 4/5
    await openAdmin(page);
    const total = { c: await countIn(companiesHeading(page)), u: await countIn(usersHeading(page)) };
    await searchBox(page).fill('zzzzxxxx-none');
    await expect(page.getByRole('heading', { name: 'חברות (0)' })).toBeVisible();
    await expect(page.getByRole('heading', { name: 'משתמשים (0)' })).toBeVisible();
    await expect(page.getByText('לא נמצאו חברות התואמות לחיפוש', { exact: true })).toBeVisible();
    await expect(page.getByText('לא נמצאו משתמשים', { exact: true })).toBeVisible();
    await searchBox(page).fill('');
    await expect(companiesHeading(page)).toHaveText(`חברות (${total.c})`);
    await expect(page.getByText('לא נמצאו חברות התואמות לחיפוש', { exact: true })).toHaveCount(0);
  });

  test('"פתיחה" בחברה מציגה את משתמשיה בלבד, "הצגת כל המשתמשים" מחזיר הכול #0fc9cd @desktop @prod-safe', async () => {
    // ACU-07 — AC (טיוטת aviel) «לראות את משתמשי כל חברה»
    await openAdmin(page);
    const total = await countIn(usersHeading(page));
    const row = rowsOf(companiesTable(page)).filter({ hasText: 'QA Company B' }).first();
    const members = Number((await row.locator('td').nth(1).innerText()).trim());
    expect(members).toBeGreaterThan(0);
    await row.getByRole('button', { name: 'פתיחה', exact: true }).click();
    await expect(row.getByRole('button', { name: 'סגירה', exact: true })).toBeVisible();
    await expect(page.getByRole('heading', { name: /^משתמשים ב-/ })).toBeVisible();
    await expect(rowsOf(usersTable(page))).toHaveCount(members);
    await expect(rowsOf(usersTable(page)).filter({ hasText: 'QA Company B' })).toHaveCount(members);
    await page.getByRole('button', { name: /^הצגת כל המשתמשים/ }).click();
    await expect(usersHeading(page)).toHaveText(`משתמשים (${total})`);
  });

  test('אישור לפני חסימה: דיאלוג "אישור פעולה" לחברה ולמשתמש, "ביטול" לא חוסם ולא שולח כלום #05b294 @desktop @prod-safe', async () => {
    // ACU-08 — דרישה 8
    await openAdmin(page);
    mutations.length = 0;

    const cRow = rowsOf(companiesTable(page)).filter({ hasText: 'QA Company B' }).first();
    const cBefore = (await cRow.innerText()).replace(/\s+/g, ' ');
    await cRow.getByRole('button', { name: 'חסימה', exact: true }).click();
    const dlg = dialogOf(page);
    await expect(dlg.getByText('אישור פעולה', { exact: true })).toBeVisible();
    await expect(dlg.getByText(/לחסום את החברה/)).toBeVisible();
    await expect(dlg.getByRole('button', { name: 'ביטול', exact: true })).toBeVisible();
    await expect(dlg.getByRole('button', { name: 'חסימה', exact: true })).toBeVisible();
    await dlg.getByRole('button', { name: 'ביטול', exact: true }).click();
    await expect(dlg).toBeHidden();
    expect((await cRow.innerText()).replace(/\s+/g, ' ')).toBe(cBefore);

    const uRow = rowsOf(usersTable(page)).filter({ hasText: 'qa-inv14' }).first();
    const uBefore = (await uRow.innerText()).replace(/\s+/g, ' ');
    await uRow.getByRole('button', { name: 'חסימה', exact: true }).click();
    await expect(dlg.getByText('אישור פעולה', { exact: true })).toBeVisible();
    await expect(dlg.getByText(/לחסום את/)).toBeVisible();
    await dlg.getByRole('button', { name: 'ביטול', exact: true }).click();
    await expect(dlg).toBeHidden();
    expect((await uRow.innerText()).replace(/\s+/g, ' ')).toBe(uBefore);

    expect(mutations, 'ביטול הדיאלוג לא אמור לשלוח שינויים לשרת').toEqual([]);
  });

  test('"יצירת חברה חדשה": טופס עם ולידציה (שם חברה, אימייל מנהל החשבון), "ביטול" לא יוצר כלום #0fc9cd @desktop @prod-safe', async () => {
    // ACU-09 — AC (טיוטת aviel): יצירת חברה; יצירה אמיתית לא נבדקת (אין מחיקת חברות)
    await openAdmin(page);
    mutations.length = 0;
    await page.getByRole('button', { name: 'יצירת חברה חדשה' }).click();
    const dlg = dialogOf(page);
    await expect(dlg.getByText('יצירת חברה חדשה', { exact: true })).toBeVisible();
    await expect(dlg.getByLabel('שם החברה')).toBeVisible();
    await expect(dlg.getByLabel('אימייל מנהל החשבון')).toBeVisible();
    await dlg.getByRole('button', { name: 'יצירה', exact: true }).click();
    await expect(dlg.getByText('יש להזין שם חברה', { exact: true })).toBeVisible();
    await expect(dlg.getByText('כתובת האימייל אינה תקינה', { exact: true })).toBeVisible();
    await dlg.getByRole('button', { name: 'ביטול', exact: true }).click();
    await expect(dlg).toBeHidden();
    expect(mutations, 'טופס לא תקין / ביטול — בלי בקשות שמשנות נתונים').toEqual([]);
  });

  test('"עריכה" בחברה פותחת טופס עם השם הנוכחי, "ביטול" לא שומר #0fc9cd @desktop @prod-safe', async () => {
    // ACU-09 — комментарий jleprog39: «עריכה» меняет только название; сохранение не нажимаем
    await openAdmin(page);
    mutations.length = 0;
    const row = rowsOf(companiesTable(page)).filter({ hasText: 'QA Company B' }).first();
    await row.getByRole('button', { name: 'עריכה', exact: true }).click();
    const dlg = dialogOf(page);
    await expect(dlg.getByText('עריכת חברה', { exact: true })).toBeVisible();
    await expect(dlg.getByLabel('שם החברה')).toHaveValue('QA Company B');
    await dlg.getByRole('button', { name: 'ביטול', exact: true }).click();
    await expect(dlg).toBeHidden();
    await expect(row).toContainText('QA Company B');
    expect(mutations, 'ביטול עריכה — בלי בקשות שמשנות נתונים').toEqual([]);
  });
});
